PRAGMA foreign_keys = ON;
CREATE TABLE tenants (id TEXT PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, email TEXT NOT NULL, display_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'ACTIVE', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tenant_id,email), FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE roles (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, name TEXT NOT NULL, permissions_json TEXT NOT NULL DEFAULT '[]', UNIQUE(tenant_id,name), FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE user_roles (user_id TEXT NOT NULL, role_id TEXT NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE documents (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, document_number TEXT NOT NULL, title TEXT NOT NULL, category TEXT, status TEXT NOT NULL DEFAULT 'DRAFT', current_version TEXT NOT NULL DEFAULT '0.1', owner_id TEXT, classification TEXT NOT NULL DEFAULT 'INTERNAL', next_review_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TEXT, UNIQUE(tenant_id,document_number), FOREIGN KEY(tenant_id) REFERENCES tenants(id), FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE document_versions (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, document_id TEXT NOT NULL, version TEXT NOT NULL, content_json TEXT, r2_object_key TEXT, sha256 TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, immutable INTEGER NOT NULL DEFAULT 0, UNIQUE(document_id,version), FOREIGN KEY(document_id) REFERENCES documents(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE approval_requests (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, document_version_id TEXT NOT NULL, step_number INTEGER NOT NULL, approver_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING', comment TEXT, decided_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(document_version_id) REFERENCES document_versions(id), FOREIGN KEY(approver_id) REFERENCES users(id));
CREATE TABLE risks (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, risk_number TEXT NOT NULL, title TEXT NOT NULL, description TEXT, owner_id TEXT, likelihood INTEGER NOT NULL CHECK(likelihood BETWEEN 1 AND 5), impact INTEGER NOT NULL CHECK(impact BETWEEN 1 AND 5), inherent_score INTEGER NOT NULL, residual_likelihood INTEGER CHECK(residual_likelihood BETWEEN 1 AND 5), residual_impact INTEGER CHECK(residual_impact BETWEEN 1 AND 5), residual_score INTEGER, status TEXT NOT NULL DEFAULT 'OPEN', review_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TEXT, UNIQUE(tenant_id,risk_number), FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE risk_measures (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, risk_id TEXT NOT NULL, title TEXT NOT NULL, owner_id TEXT, due_at TEXT, status TEXT NOT NULL DEFAULT 'OPEN', effectiveness TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(risk_id) REFERENCES risks(id));
CREATE TABLE kpis (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, kpi_number TEXT NOT NULL, name TEXT NOT NULL, description TEXT, owner_id TEXT, unit TEXT, target_value REAL, warning_value REAL, critical_value REAL, frequency TEXT NOT NULL DEFAULT 'MONTHLY', status TEXT NOT NULL DEFAULT 'ACTIVE', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TEXT, UNIQUE(tenant_id,kpi_number), FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE kpi_measurements (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, kpi_id TEXT NOT NULL, measured_at TEXT NOT NULL, value REAL NOT NULL, comment TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(kpi_id,measured_at), FOREIGN KEY(kpi_id) REFERENCES kpis(id));
CREATE TABLE tasks (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, title TEXT NOT NULL, assignee_id TEXT, entity_type TEXT, entity_id TEXT, status TEXT NOT NULL DEFAULT 'OPEN', due_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_logs (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, actor_id TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, action TEXT NOT NULL, details_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_documents_tenant_status ON documents(tenant_id,status);
CREATE INDEX idx_risks_tenant_status ON risks(tenant_id,status);
CREATE INDEX idx_kpis_tenant_status ON kpis(tenant_id,status);
CREATE INDEX idx_audit_entity ON audit_logs(tenant_id,entity_type,entity_id,created_at);
